/**
 * NavMeshGrid - Navigation mesh for pathfinding
 *
 * @extends THREE.EventDispatcher
 */
export class NavMeshGrid {
    /**
     * @param {Object} config - Configuration options
     * @param {THREE.Mesh} [config.mesh] - Source mesh for navmesh extraction (Mode 1)
     * @param {THREE.Box3} [config.bounds] - World bounds for BVH generation (Mode 2)
     * @param {number} [config.cellSize=1.0] - Cell size for BVH sampling resolution
     * @param {number} [config.maxSlope=Math.PI/4] - Maximum walkable slope in radians (45 degrees)
     * @param {number} [config.agentHeight=1.8] - Height of agents using this navmesh
     * @param {number} [config.agentRadius=0.5] - Collision radius of agents
     * @param {boolean} [config.mergeTriangles=false] - Whether to merge coplanar triangles
     */
    constructor(config?: {
        mesh?: THREE.Mesh;
        bounds?: THREE.Box3;
        cellSize?: number;
        maxSlope?: number;
        agentHeight?: number;
        agentRadius?: number;
        mergeTriangles?: boolean;
    });
    /**
     * Source mesh for navmesh geometry (Mode 1).
     * @type {THREE.Mesh|null}
     */
    mesh: THREE.Mesh | null;
    /**
     * World bounds for BVH-based generation (Mode 2).
     * @type {THREE.Box3|null}
     */
    bounds: THREE.Box3 | null;
    /**
     * Cell size for BVH sampling resolution.
     * @type {number}
     */
    cellSize: number;
    /**
     * Maximum walkable slope in radians.
     * @type {number}
     */
    maxSlope: number;
    /**
     * Height of agents using this navmesh.
     * @type {number}
     */
    agentHeight: number;
    /**
     * Collision radius of agents.
     * @type {number}
     */
    agentRadius: number;
    /**
     * Whether to merge coplanar adjacent triangles.
     * @type {boolean}
     */
    mergeTriangles: boolean;
    /**
     * Physics instance reference.
     * @type {Object|null}
     * @private
     */
    private _physics;
    /**
     * Whether the navmesh has been initialized.
     * @type {boolean}
     * @private
     */
    private _initialized;
    /**
     * Whether the navmesh has been compiled.
     * @type {boolean}
     * @private
     */
    private _compiled;
    /**
     * Compiled navmesh data for transfer to worker.
     * @type {Object|null}
     * @private
     */
    private _compiledData;
    /**
     * Three.js-style type flag.
     * @type {boolean}
     */
    isNavMeshGrid: boolean;
    /**
     * Initialize the navmesh with a Physics instance.
     * Must be called before compile().
     *
     * @param {Object} physics - Physics instance
     * @returns {Promise<NavMeshGrid>} This instance for chaining
     * @throws {Error} If physics or physicsApi is not available
     */
    init(physics: any): Promise<NavMeshGrid>;
    /**
     * Compile the navigation mesh.
     * Extracts polygons from mesh or generates from BVH, builds edges,
     * and sends data to the worker.
     *
     * @returns {Promise<NavMeshGrid>} This instance for chaining
     * @throws {Error} If not initialized or no mesh/bounds provided
     */
    compile(): Promise<NavMeshGrid>;
    /**
     * Extract walkable polygons from mesh geometry.
     * Filters triangles by slope angle.
     *
     * @returns {Array<{vertices: Array, normal: THREE.Vector3}>} Walkable polygons
     * @private
     */
    private _extractFromMesh;
    /**
     * Generate navmesh from scene static bodies using BVH raycasts.
     * Samples a grid of points and builds triangles from walkable samples.
     *
     * @returns {Promise<Array<{vertices: Array, normal: THREE.Vector3}>>} Walkable polygons
     * @private
     */
    private _generateFromBVH;
    /**
     * Triangulate grid samples into navmesh polygons.
     * Creates triangles from adjacent walkable samples.
     *
     * @param {Array<{gx: number, gz: number, y: number, walkable: boolean}>} samples - Grid samples
     * @param {number} cellSize - Grid cell size
     * @returns {Array<{vertices: Array, normal: THREE.Vector3}>} Triangulated polygons
     * @private
     */
    private _triangulateGrid;
    /**
     * Merge coplanar adjacent triangles into larger polygons.
     * Optimization to reduce polygon count.
     *
     * @param {Array<{vertices: Array, normal: THREE.Vector3}>} triangles - Input triangles
     * @returns {Array<{vertices: Array, normal: THREE.Vector3}>} Merged polygons
     * @private
     */
    private _mergeCoplanarTriangles;
    /**
     * Build edge adjacency map.
     * Finds shared edges between polygons for neighbor relationships.
     *
     * @param {Array<{vertices: Array, normal: THREE.Vector3}>} polygons - Navmesh polygons
     * @returns {Map<string, {poly1Index: number, poly2Index: number, portal: Object}>} Edge map
     * @private
     */
    private _buildEdges;
    /**
     * Create deterministic edge hash.
     * Sorts vertices to ensure consistent hash regardless of direction.
     *
     * @param {Object} v1 - First vertex
     * @param {Object} v2 - Second vertex
     * @returns {string} Edge hash
     * @private
     */
    private _edgeHash;
    /**
     * Get compiled navmesh data for visualization.
     *
     * @returns {Object|null} Compiled data or null if not compiled
     */
    getCompiledData(): any | null;
    /**
     * Get debug info about the navmesh.
     *
     * @returns {Promise<Object>} Debug information
     */
    getDebugInfo(): Promise<any>;
    /**
     * Whether the navmesh has been initialized.
     * @type {boolean}
     * @readonly
     */
    readonly get initialized(): boolean;
    /**
     * Whether the navmesh has been compiled.
     * @type {boolean}
     * @readonly
     */
    readonly get compiled(): boolean;
    /**
     * Get the physics instance.
     * @type {Object|null}
     * @readonly
     */
    readonly get physics(): any | null;
    /**
     * Dispose of the navigation mesh.
     * Releases references and clears compiled data.
     */
    dispose(): void;
}
